head.script:
scwin.trigger2_onclick = function(e) {
	var json = dataList1.getAllJSON();
	json.forEach(function(o) {
		o["MENU_NM"] = o["MENU_NM"].replace(/<([^>]+)>/gi, ""); // 태그제거
	});
	dataList1.setJSON(json);
	treeview1.spanAll(true);
	var word = input1.getValue();
	var arr_idx = dataList1.getMatchedIndex("MENU_NM", word, false);
	arr_idx.forEach(function(ix) {
		var label = dataList1.getCellData(ix, "MENU_NM");
		dataList1.setCellData(ix, "MENU_NM", label.replaceAll(word, "<span style='color:red'>" + word + "</span>"));
	});
};
scwin.onpageload = function() {
	dataList1.setJSON([
		{"MENU_ID": "menu1", "MENU_NM": "menu1", "LEVEL_CNT": "1", "rowStatus": "R"},
		{"MENU_ID": "menu1-1", "MENU_NM": "menu1-1", "LEVEL_CNT": "2", "rowStatus": "R"},
		{"MENU_ID": "menu1-1-1", "MENU_NM": "menu1-1-1", "LEVEL_CNT": "3", "rowStatus": "R"},
		{"MENU_ID": "menu1-1-2", "MENU_NM": "menu1-1-2", "LEVEL_CNT": "3", "rowStatus": "R"},
		{"MENU_ID": "menu1-2", "MENU_NM": "menu1-2", "LEVEL_CNT": "2", "rowStatus": "R"},
		{"MENU_ID": "menu1-2-1", "MENU_NM": "menu1-2-1", "LEVEL_CNT": "3", "rowStatus": "R"},
		{"MENU_ID": "menu1-2-1-1", "MENU_NM": "menu1-2-1-1", "LEVEL_CNT": "4", "rowStatus": "R"},
		{"MENU_ID": "menu1-2-1-2", "MENU_NM": "menu1-2-1-2", "LEVEL_CNT": "4", "rowStatus": "R"},
		{"MENU_ID": "menu2", "MENU_NM": "menu2", "LEVEL_CNT": "1", "rowStatus": "R"},
		{"MENU_ID": "menu2-1", "MENU_NM": "menu2-1", "LEVEL_CNT": "2", "rowStatus": "R"}
	]);
	treeview1.spanAll(true);
	input1.setValue("menu1-1");
};
